-- Stores the frozen A13Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a13q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A13Q';
 v_cp constant text := 'A13Q_C2';
 v_wi constant bigint := 1123;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A13Q_C2';
 v_packet_sha constant text := '2a9a4ab0a3b3b46b3be8bc3fd952737dee7aa44ff429ff8624e58738b4b49b5f';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"bv_keys":["contract","logic_head"],"disp_keys":["disposition","finding_ref","reason"],"dispositions":["NO_CHANGE","REQUIRES_MODEL_CHANGE"],"hb_keys":["holdout_used_for_tuning"],"mc_keys":["after_version_label","before_version","case_specific_patch","change_rule","generalization_properties","hardcodes_case_family","root_finding_code","root_finding_ref","target_component","unchanged_components"],"no_change_pattern":"(^|_)0_CRITICAL","request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001","rp_keys":["executed","observed_result","planned_checks"],"target_component":"change_classification_contract"},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"before_version\": {\n    \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n    \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n  },\n  \"findings\": [\n    {\n      \"ref\": \"lf_eventos://20527\",\n      \"result\": \"30_CASES_0_CRITICAL_OMISSIONS\",\n      \"unit\": \"A10\"\n    },\n    {\n      \"ref\": \"lf_eventos://20532\",\n      \"result\": \"11_ADVERSARIAL_TYPES_0_CRITICAL_FALSE_READY\",\n      \"unit\": \"A11\"\n    },\n    {\n      \"ref\": \"lf_eventos://20534\",\n      \"result\": \"CANDIDATE_0_CRITICAL_FALSE_NEGATIVES_IN_CONTRACT_REPLAY\",\n      \"unit\": \"A12\"\n    },\n    {\n      \"ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"result\": \"DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"unit\": \"A14_PREFLIGHT\"\n    }\n  ],\n  \"method_description\": \"Método no especializado vigente: el paquete de análisis clasifica la profundidad de cada cambio con un vocabulario de señales gobernadas, sin una política explícita que defina qué significa cada nivel de profundidad. Un cambio de método válido debe ser general (aplicable a cualquier familia de cambios), no un parche para un caso, y debe indicar qué versión cambia, a cuál pasa y cuál es el hallazgo raíz exacto.\",\n  \"model_components\": [\n    {\n      \"component\": \"change_classification_contract\",\n      \"governs\": \"clasifica la profundidad del análisis de un cambio en niveles L1, L2 y L3\"\n    },\n    {\n      \"component\": \"handoff_contract\",\n      \"governs\": \"define el traspaso de artefactos entre etapas\"\n    },\n    {\n      \"component\": \"impact_model\",\n      \"governs\": \"determina qué elementos impacta un cambio\"\n    },\n    {\n      \"component\": \"specialist_selection\",\n      \"governs\": \"decide qué especialistas participan en el análisis\"\n    },\n    {\n      \"component\": \"stop_rule\",\n      \"governs\": \"decide cuándo el análisis debe detenerse por falta de evidencia o decisión\"\n    }\n  ],\n  \"root_finding_candidates\": [\n    {\n      \"code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"evidence_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n      \"generalizable\": true,\n      \"severity\": \"HIGH\"\n    }\n  ],\n  \"schema_version\": \"A13_INPUT_FINDINGS_V1\"\n}","input_origin":"A13 findings fixture (b0299a3ceb323fafebb397992ea68f8936839852b715419e891f5c9e91d1a080)","input_sha256":"b0299a3ceb323fafebb397992ea68f8936839852b715419e891f5c9e91d1a080","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","dispositions","method_change","regression_plan","holdout_boundary","no_ready_claim","change_statement"],"schema":"A13_METHOD_CHANGE_OUTPUT_V1","validator":"analysis_qualification_a13q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"2a9a4ab0a3b3b46b3be8bc3fd952737dee7aa44ff429ff8624e58738b4b49b5f","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A13 (cambio de método) del perfil de análisis. Recibes los hallazgos de las etapas anteriores (findings), la versión actual (before_version), el candidato a hallazgo raíz (root_finding_candidates) y los componentes del modelo (model_components) (abajo). NO se re-ejecuta nada: solo PROPONES el cambio de método. Para cada hallazgo decide si exige cambiar el modelo o no, según su resultado. Si alguno lo exige, propón UN cambio general (aplicable a cualquier familia de cambios, no un parche para un caso). Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, dispositions, method_change, regression_plan, holdout_boundary, no_ready_claim, change_statement. schema_version='A13_METHOD_CHANGE_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. dispositions: lista con un registro por hallazgo, con exactamente las claves disposition, finding_ref, reason: finding_ref (la ref del hallazgo), disposition: NO_CHANGE|REQUIRES_MODEL_CHANGE, reason (texto de al menos 20 caracteres). method_change: objeto con exactamente las claves after_version_label, before_version, case_specific_patch, change_rule, generalization_properties, hardcodes_case_family, root_finding_code, root_finding_ref, target_component, unchanged_components: root_finding_code y root_finding_ref copiados del candidato a hallazgo raíz; target_component: un componente de model_components; before_version: objeto con exactamente las claves contract, logic_head igual a la versión actual suministrada; after_version_label: texto propuesto de al menos 8 caracteres para la versión resultante, distinto del logic_head actual y que NO sea un hash de 40 caracteres hexadecimales (no se creó ningún commit); change_rule: texto de al menos 80 caracteres que describa la regla general propuesta; generalization_properties: lista de al menos 3 textos distintos de al menos 10 caracteres; case_specific_patch: false; hardcodes_case_family: false; unchanged_components: lista con los componentes que NO cambian (subconjunto de model_components, sin incluir el target_component). regression_plan: objeto con exactamente las claves executed, observed_result, planned_checks: planned_checks lista de al menos 2 textos de al menos 10 caracteres; executed: false; observed_result: null (nada se ejecutó). holdout_boundary: objeto con exactamente la clave holdout_used_for_tuning: false. no_ready_claim=true. change_statement: texto de al menos 40 caracteres que diga que el cambio es una propuesta no ejecutada ni verificada. No incluyas latencia, tokens, proveedor ni identificadores de ejecución.\n\nENTRADA (JSON):\n{\n  \"before_version\": {\n    \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n    \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n  },\n  \"findings\": [\n    {\n      \"ref\": \"lf_eventos://20527\",\n      \"result\": \"30_CASES_0_CRITICAL_OMISSIONS\",\n      \"unit\": \"A10\"\n    },\n    {\n      \"ref\": \"lf_eventos://20532\",\n      \"result\": \"11_ADVERSARIAL_TYPES_0_CRITICAL_FALSE_READY\",\n      \"unit\": \"A11\"\n    },\n    {\n      \"ref\": \"lf_eventos://20534\",\n      \"result\": \"CANDIDATE_0_CRITICAL_FALSE_NEGATIVES_IN_CONTRACT_REPLAY\",\n      \"unit\": \"A12\"\n    },\n    {\n      \"ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"result\": \"DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"unit\": \"A14_PREFLIGHT\"\n    }\n  ],\n  \"method_description\": \"Método no especializado vigente: el paquete de análisis clasifica la profundidad de cada cambio con un vocabulario de señales gobernadas, sin una política explícita que defina qué significa cada nivel de profundidad. Un cambio de método válido debe ser general (aplicable a cualquier familia de cambios), no un parche para un caso, y debe indicar qué versión cambia, a cuál pasa y cuál es el hallazgo raíz exacto.\",\n  \"model_components\": [\n    {\n      \"component\": \"change_classification_contract\",\n      \"governs\": \"clasifica la profundidad del análisis de un cambio en niveles L1, L2 y L3\"\n    },\n    {\n      \"component\": \"handoff_contract\",\n      \"governs\": \"define el traspaso de artefactos entre etapas\"\n    },\n    {\n      \"component\": \"impact_model\",\n      \"governs\": \"determina qué elementos impacta un cambio\"\n    },\n    {\n      \"component\": \"specialist_selection\",\n      \"governs\": \"decide qué especialistas participan en el análisis\"\n    },\n    {\n      \"component\": \"stop_rule\",\n      \"governs\": \"decide cuándo el análisis debe detenerse por falta de evidencia o decisión\"\n    }\n  ],\n  \"root_finding_candidates\": [\n    {\n      \"code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"evidence_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n      \"generalizable\": true,\n      \"severity\": \"HIGH\"\n    }\n  ],\n  \"schema_version\": \"A13_INPUT_FINDINGS_V1\"\n}","request_sha256":"dd0188cff84a52e4c6db8c550ad7d039a9c20245f76d42d4800127bdb2eb49af","run_id":"A13Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A13","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A13Q/A13Q_C2","unit":"A13"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A13Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A13Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A13Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A13Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A13Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A13Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A13Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A13Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A13Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A13Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A13Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A13Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A13Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A13Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A13Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A13Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A13Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a13q_c2_prep$;
COMMIT;
